class King extends Piece {
    King(Color color) { super(color); }

    @Override
    boolean isKing() { return true; }

    @Override
    boolean isValidMove(Position from, Position to, Board board) {
        int rowDiff = Math.abs(to.row-from.row);
        int colDiff = Math.abs(to.col-from.col);
        return rowDiff <= 1 && colDiff <= 1 && !(rowDiff == 0 && colDiff == 0);
    }
}

class Rook extends Piece {
    Rook(Color color) { super(color); }

    @Override
    boolean isValidMove(Position from, Position to, Board board) {
        if (from.row != to.row && from.col != to.col) return false;
        return board.isPathClear(from, to);
    }
}

class Bishop extends Piece {
    Bishop(Color color) { super(color); }

    @Override
    boolean isValidMove(Position from, Position to, Board board) {
        int rowDiff = Math.abs(to.row-from.row);
        int colDiff = Math.abs(to.col-from.col);
        if (rowDiff != colDiff || rowDiff == 0) return false;
        return board.isPathClear(from, to);
    }
}

