    private Piece[][] squares = new Piece[8][8];

    void placePiece(Position pos, Piece piece) {
        squares[pos.row][pos.col] = piece;
    }

    Piece getPiece(Position pos) {
        return squares[pos.row][pos.col];
    }

    boolean isPathClear(Position from, Position to) {
        int rowStep = Integer.compare(to.row, from.row);
        int colStep = Integer.compare(to.col, from.col);
        int r = from.row + rowStep;
        int c = from.col + colStep;
        while (r != to.row || c != to.col) {
            if (squares[r][c] != null) return false;
            r += rowStep;
            c += colStep;
        }
        return true;
    }

    void movePiece(Position from, Position to) {
        Piece piece = squares[from.row][from.col];
        squares[to.row][to.col] = piece;
        squares[from.row][from.col] = null;
    }

    Position findKing(Color color) {
        for (int r = 0; r < 8; r++) {
            for (int c = 0; c < 8; c++) {
                Piece piece = squares[r][c];
                if (piece != null && piece.isKing() && piece.getColor() == color) {
                    return new Position(r, c);
                }
            }
        }
        return null;
    }

    boolean isSquareAttacked(Position target, Color byColor) {
        for (int r = 0; r < 8; r++) {
            for (int c = 0; c < 8; c++) {
