// Command pattern: a move is captured as an object that can both execute
// and undo itself, essential for safely testing "would this leave my king in check"
class MoveCommand {
    private Board board;
    private Position from;
    private Position to;
    private Piece movedPiece;
    private Piece capturedPiece;

    MoveCommand(Board board, Position from, Position to) {
        this.board = board;
        this.from = from;
        this.to = to;
    }

    void execute() {
        movedPiece = board.getPiece(from);
        capturedPiece = board.getPiece(to);
        board.movePiece(from, to);
    }

    void undo() {
        board.placePiece(from, movedPiece);
        board.placePiece(to, capturedPiece);
    }
}

