import java.util.ArrayList;
import java.util.List;

public class ChessGame {
    private Board board;
    private Color currentTurn;
    private List<MoveCommand> history = new ArrayList<>();

    public ChessGame() {
        board = new Board();
        currentTurn = Color.WHITE;
        setupBoard();
    }

    private void setupBoard() {
        board.placePiece(new Position(0, 0), PieceFactory.createPiece("ROOK", Color.WHITE));
        board.placePiece(new Position(0, 4), PieceFactory.createPiece("KING", Color.WHITE));
        board.placePiece(new Position(0, 5), PieceFactory.createPiece("BISHOP", Color.WHITE));
        board.placePiece(new Position(7, 0), PieceFactory.createPiece("ROOK", Color.BLACK));
        board.placePiece(new Position(7, 4), PieceFactory.createPiece("KING", Color.BLACK));
        board.placePiece(new Position(7, 5), PieceFactory.createPiece("BISHOP", Color.BLACK));
    }

    public boolean makeMove(Position from, Position to) {
        Piece piece = board.getPiece(from);
        if (piece == null || piece.getColor() != currentTurn) {
            return false;
        }
        if (!piece.isValidMove(from, to, board)) {
            return false;
        }
        Piece target = board.getPiece(to);
        if (target != null && target.getColor() == piece.getColor()) {
            return false;
        }

        MoveCommand move = new MoveCommand(board, from, to);
        move.execute();

        if (isKingInCheck(currentTurn)) {
            move.undo();
            return false;
        }

        history.add(move);
        currentTurn = (currentTurn == Color.WHITE) ? Color.BLACK : Color.WHITE;
        return true;
    }

    public boolean isKingInCheck(Color color) {
        Position kingPos = board.findKing(color);
        Color opponent = (color == Color.WHITE) ? Color.BLACK : Color.WHITE;
        return board.isSquareAttacked(kingPos, opponent);
    }

    public Color getCurrentTurn() {
        return currentTurn;
    }
}

