#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <stdexcept>
using namespace std;

enum class Color { WHITE, BLACK };

string colorName(Color c) {
    return c == Color::WHITE ? "WHITE" : "BLACK";
}

class Position {
public:
    int row, col;
    Position(int row, int col) : row(row), col(col) {}
};

class Board;

class Piece {
protected:
    Color color;
public:
    Piece(Color color) : color(color) {}
    Color getColor() { return color; }
    virtual bool isKing() { return false; }
    virtual bool isValidMove(Position from, Position to, Board& board) = 0;
    virtual ~Piece() {}
};

class King : public Piece {
public:
    King(Color color) : Piece(color) {}
    bool isKing() override { return true; }
    bool isValidMove(Position from, Position to, Board& board) override;
};

class Rook : public Piece {
public:
    Rook(Color color) : Piece(color) {}
    bool isValidMove(Position from, Position to, Board& board) override;
};

class Bishop : public Piece {
public:
    Bishop(Color color) : Piece(color) {}
    bool isValidMove(Position from, Position to, Board& board) override;
};

class PieceFactory {
public:
    static Piece* createPiece(string type, Color color) {
        if (type == "KING") return new King(color);
        if (type == "ROOK") return new Rook(color);
        if (type == "BISHOP") return new Bishop(color);
        throw invalid_argument("Unknown piece type: " + type);
    }
};

class Board {
private:
    Piece* squares[8][8];

public:
    Board() {
        for (int r = 0; r < 8; r++)
            for (int c = 0; c < 8; c++)
                squares[r][c] = nullptr;
    }

    void placePiece(Position pos, Piece* piece) {
        squares[pos.row][pos.col] = piece;
    }

    Piece* getPiece(Position pos) {
        return squares[pos.row][pos.col];
    }

    bool isPathClear(Position from, Position to) {
        int rowStep = (to.row > from.row)-(to.row < from.row);
        int colStep = (to.col > from.col)-(to.col < from.col);
        int r = from.row + rowStep;
        int c = from.col + colStep;
        while (r != to.row || c != to.col) {
            if (squares[r][c] != nullptr) return false;
            r += rowStep;
            c += colStep;
        }
        return true;
    }

    void movePiece(Position from, Position to) {
        Piece* piece = squares[from.row][from.col];
        squares[to.row][to.col] = piece;
        squares[from.row][from.col] = nullptr;
    }

    Position findKing(Color color) {
        for (int r = 0; r < 8; r++) {
            for (int c = 0; c < 8; c++) {
                Piece* piece = squares[r][c];
                if (piece != nullptr && piece->isKing() && piece->getColor() == color) {
                    return Position(r, c);
                }
            }
        }
        return Position(-1, -1);
    }

    bool isSquareAttacked(Position target, Color byColor) {
        for (int r = 0; r < 8; r++) {
            for (int c = 0; c < 8; c++) {
                Piece* piece = squares[r][c];
                if (piece != nullptr && piece->getColor() == byColor) {
                    if (piece->isValidMove(Position(r, c), target, *this)) return true;
                }
            }
        }
        return false;
    }
};

bool King::isValidMove(Position from, Position to, Board& board) {
    int rowDiff = abs(to.row-from.row);
    int colDiff = abs(to.col-from.col);
    return rowDiff <= 1 && colDiff <= 1 && !(rowDiff == 0 && colDiff == 0);
}

bool Rook::isValidMove(Position from, Position to, Board& board) {
    if (from.row != to.row && from.col != to.col) return false;
    return board.isPathClear(from, to);
}

bool Bishop::isValidMove(Position from, Position to, Board& board) {
    int rowDiff = abs(to.row-from.row);
    int colDiff = abs(to.col-from.col);
    if (rowDiff != colDiff || rowDiff == 0) return false;
    return board.isPathClear(from, to);
}

class MoveCommand {
private:
    Board* board;
    Position from;
    Position to;
    Piece* movedPiece;
    Piece* capturedPiece;

public:
    MoveCommand(Board* board, Position from, Position to)
        : board(board), from(from), to(to), movedPiece(nullptr), capturedPiece(nullptr) {}

    void execute() {
        movedPiece = board->getPiece(from);
        capturedPiece = board->getPiece(to);
        board->movePiece(from, to);
    }

    void undo() {
        board->placePiece(from, movedPiece);
        board->placePiece(to, capturedPiece);
    }
};

class ChessGame {
private:
    Board board;
    Color currentTurn;
    vector<MoveCommand> history;

    void setupBoard() {
        board.placePiece(Position(0, 0), PieceFactory::createPiece("ROOK", Color::WHITE));
        board.placePiece(Position(0, 4), PieceFactory::createPiece("KING", Color::WHITE));
        board.placePiece(Position(0, 5), PieceFactory::createPiece("BISHOP", Color::WHITE));
        board.placePiece(Position(7, 0), PieceFactory::createPiece("ROOK", Color::BLACK));
        board.placePiece(Position(7, 4), PieceFactory::createPiece("KING", Color::BLACK));
        board.placePiece(Position(7, 5), PieceFactory::createPiece("BISHOP", Color::BLACK));
    }

public:
    ChessGame() : currentTurn(Color::WHITE) {
        setupBoard();
    }

    bool makeMove(Position from, Position to) {
        Piece* piece = board.getPiece(from);
        if (piece == nullptr || piece->getColor() != currentTurn) {
            return false;
        }
        if (!piece->isValidMove(from, to, board)) {
            return false;
        }
        Piece* target = board.getPiece(to);
        if (target != nullptr && target->getColor() == piece->getColor()) {
            return false;
        }

        MoveCommand move(&board, from, to);
        move.execute();

        if (isKingInCheck(currentTurn)) {
            move.undo();
            return false;
        }

        history.push_back(move);
        currentTurn = (currentTurn == Color::WHITE) ? Color::BLACK : Color::WHITE;
        return true;
    }

    bool isKingInCheck(Color color) {
        Position kingPos = board.findKing(color);
        Color opponent = (color == Color::WHITE) ? Color::BLACK : Color::WHITE;
        return board.isSquareAttacked(kingPos, opponent);
    }

    Color getCurrentTurn() {
        return currentTurn;
    }
};

int main() {
    ChessGame game;

    bool move1 = game.makeMove(Position(0, 0), Position(0, 3));
    cout << "Move 1 (Rook a1-d1): " << (move1 ? "true" : "false") << ", turn now: " << colorName(game.getCurrentTurn()) << endl;

    bool move2 = game.makeMove(Position(7, 0), Position(7, 3));
    cout << "Move 2 (Rook a8-d8): " << (move2 ? "true" : "false") << ", turn now: " << colorName(game.getCurrentTurn()) << endl;

    bool invalidMove = game.makeMove(Position(0, 4), Position(2, 4));
    cout << "Move 3 (King illegal 2-square): " << (invalidMove ? "true" : "false") << endl;

    bool move4 = game.makeMove(Position(0, 4), Position(1, 4));
    cout << "Move 4 (King one step): " << (move4 ? "true" : "false") << endl;

    return 0;
}
